{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2199-01-26 18:00:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee. I’ll be taking care of you during your stay. Can you tell me what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2199-01-26 18:02:00",
      "speaker": "Patient",
      "text": "Hi, Doctor. I’ve been feeling weak and not eating much. I’ve had diarrhea for about two weeks now, and I’ve lost weight."
    },
    {
      "turn_number": 3,
      "time": "2199-01-26 18:04:00",
      "speaker": "Doctor",
      "text": "I see. Your primary doctor mentioned your kidney numbers were high and you were dehydrated. You’ve also lost about 10 pounds recently?"
    },
    {
      "turn_number": 4,
      "time": "2199-01-26 18:05:00",
      "speaker": "Patient",
      "text": "Yes, I haven’t had much appetite. I feel cold all the time and just tired. I haven’t been urinating much either."
    },
    {
      "turn_number": 5,
      "time": "2199-01-26 18:07:00",
      "speaker": "Doctor",
      "text": "That makes sense. Dehydration can affect your kidneys. We’ve started you on IV fluids to help with that. Your creatinine was high at 3.6, but it’s already coming down."
    },
    {
      "turn_number": 6,
      "time": "2199-01-26 18:09:00",
      "speaker": "Patient",
      "text": "Is that serious? My kidneys have always been a little off since the transplant."
    },
    {
      "turn_number": 7,
      "time": "2199-01-26 18:11:00",
      "speaker": "Doctor",
      "text": "It’s an acute issue on top of your chronic kidney disease. We think it’s due to the diarrhea and not drinking enough. With fluids, it’s improving. We’ll keep monitoring it."
    },
    {
      "turn_number": 8,
      "time": "2199-01-26 18:13:00",
      "speaker": "Patient",
      "text": "Okay, that’s a relief. What about the diarrhea? It’s been watery and constant."
    },
    {
      "turn_number": 9,
      "time": "2199-01-26 18:15:00",
      "speaker": "Doctor",
      "text": "We tested your stool. It’s not C. diff or a common bacterial infection. We’re still waiting on some viral and parasite tests, but no treatment is needed right now."
    },
    {
      "turn_number": 10,
      "time": "2199-01-26 18:17:00",
      "speaker": "Patient",
      "text": "I had C. diff before. I was worried it came back."
    },
    {
      "turn_number": 11,
      "time": "2199-01-26 18:19:00",
      "speaker": "Doctor",
      "text": "No, it’s not C. diff this time. Your immune system is suppressed, so we have to be careful, but so far nothing dangerous shows up."
    },
    {
      "turn_number": 12,
      "time": "2199-01-26 18:21:00",
      "speaker": "Patient",
      "text": "I’ve also been feeling shaky and unsteady, like I’m walking drunk."
    },
    {
      "turn_number": 13,
      "time": "2199-01-26 18:23:00",
      "speaker": "Doctor",
      "text": "That could be from your essential tremor or maybe weakness from not eating. We’ll check your electrolytes and make sure nothing else is going on."
    },
    {
      "turn_number": 14,
      "time": "2199-01-26 18:25:00",
      "speaker": "Patient",
      "text": "I take Prograf for my liver. Could that be off?"
    },
    {
      "turn_number": 15,
      "time": "2199-01-26 18:27:00",
      "speaker": "Doctor",
      "text": "Good point. Your level came back high—12.6, which is above the usual range. That’s likely because of the diarrhea affecting absorption. We’ll lower your dose."
    },
    {
      "turn_number": 16,
      "time": "2199-01-26 18:29:00",
      "speaker": "Patient",
      "text": "Will that help me feel better?"
    },
    {
      "turn_number": 17,
      "time": "2199-01-26 18:31:00",
      "speaker": "Doctor",
      "text": "It should. High levels can cause tremors and confusion. We’re reducing it to 1 mg twice a day. You’ll need to check the level again tomorrow morning before your dose."
    },
    {
      "turn_number": 18,
      "time": "2199-01-26 18:33:00",
      "speaker": "Patient",
      "text": "Okay, I’ll do that. What about my liver? I still have hepatitis C."
    },
    {
      "turn_number": 19,
      "time": "2199-01-26 18:35:00",
      "speaker": "Doctor",
      "text": "Yes, your viral load is still high, but your liver doctors think we can consider treatment now since your kidney function is improving."
    },
    {
      "turn_number": 20,
      "time": "2199-01-26 18:37:00",
      "speaker": "Patient",
      "text": "I didn’t take it before because my kidneys were too weak."
    },
    {
      "turn_number": 21,
      "time": "2199-01-26 18:39:00",
      "speaker": "Doctor",
      "text": "Exactly. Now that your creatinine is coming down, it might be safe. We’ll discuss it with your liver team after discharge."
    },
    {
      "turn_number": 22,
      "time": "2199-01-26 18:41:00",
      "speaker": "Patient",
      "text": "That sounds good. I’ve been so down lately. I don’t enjoy eating or doing anything."
    },
    {
      "turn_number": 23,
      "time": "2199-01-26 18:43:00",
      "speaker": "Doctor",
      "text": "I understand. You’re on mirtazapine, which helps with both appetite and mood. We’ll keep that going. Depression is common with chronic illness."
    },
    {
      "turn_number": 24,
      "time": "2199-01-26 18:45:00",
      "speaker": "Patient",
      "text": "Thank you. I’ve also been coughing a little, but no fever."
    },
    {
      "turn_number": 25,
      "time": "2199-01-26 18:47:00",
      "speaker": "Doctor",
      "text": "We did a chest X-ray. It shows some old scarring in your lung, but no pneumonia. Your heart size is normal too."
    },
    {
      "turn_number": 26,
      "time": "2199-01-26 18:49:00",
      "speaker": "Patient",
      "text": "I traveled for my niece’s funeral recently. I thought maybe I caught something."
    },
    {
      "turn_number": 27,
      "time": "2199-01-26 18:51:00",
      "speaker": "Doctor",
      "text": "No signs of infection now. The cough might just be from dry air or irritation. Keep an eye on it, but I’m not worried."
    },
    {
      "turn_number": 28,
      "time": "2199-01-27 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs are improving. Creatinine is down to 1.5, and your acid levels are normalizing."
    },
    {
      "turn_number": 29,
      "time": "2199-01-27 09:02:00",
      "speaker": "Patient",
      "text": "That’s great! Is the diarrhea gone?"
    },
    {
      "turn_number": 30,
      "time": "2199-01-27 09:04:00",
      "speaker": "Doctor",
      "text": "Yes, it resolved yesterday. That’s a big reason your kidneys are recovering. We’ll keep you on fluids today and see how you do."
    },
    {
      "turn_number": 31,
      "time": "2199-01-27 09:06:00",
      "speaker": "Patient",
      "text": "I’m feeling a bit stronger. Can I eat something light?"
    },
    {
      "turn_number": 32,
      "time": "2199-01-27 09:08:00",
      "speaker": "Doctor",
      "text": "Yes, start with small amounts—broth, toast. Your stomach has been through a lot. We’ll advance as tolerated."
    },
    {
      "turn_number": 33,
      "time": "2199-01-27 14:00:00",
      "speaker": "Doctor",
      "text": "Your urine culture showed E. coli, but since you have no symptoms of a UTI, we won’t treat it. It’s likely from old infections."
    },
    {
      "turn_number": 34,
      "time": "2199-01-27 14:02:00",
      "speaker": "Patient",
      "text": "I’ve had UTIs before. Should I be concerned?"
    },
    {
      "turn_number": 35,
      "time": "2199-01-27 14:04:00",
      "speaker": "Doctor",
      "text": "Not right now. You’re not running a fever or having pain. We’ll watch it, but no antibiotics are needed."
    },
    {
      "turn_number": 36,
      "time": "2199-01-28 10:00:00",
      "speaker": "Doctor",
      "text": "Your CMV and other virus tests came back negative. No parasites either. That’s good news."
    },
    {
      "turn_number": 37,
      "time": "2199-01-28 10:02:00",
      "speaker": "Patient",
      "text": "So nothing serious is causing the diarrhea?"
    },
    {
      "turn_number": 38,
      "time": "2199-01-28 10:04:00",
      "speaker": "Doctor",
      "text": "Not that we can find. It may have just been from a mild virus or your medications. Since it’s resolved, we’ll focus on recovery."
    },
    {
      "turn_number": 39,
      "time": "2199-01-29 08:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Your labs are stable, and you’re eating and drinking. We’re planning to discharge you today."
    },
    {
      "turn_number": 40,
      "time": "2199-01-29 08:02:00",
      "speaker": "Patient",
      "text": "That’s good. What do I need to do after I go home?"
    },
    {
      "turn_number": 41,
      "time": "2199-01-29 08:04:00",
      "speaker": "Doctor",
      "text": "First, check your tacrolimus level tomorrow morning before your dose. Call your liver doctor with the result."
    },
    {
      "turn_number": 42,
      "time": "2199-01-29 08:06:00",
      "speaker": "Patient",
      "text": "I remember. And keep drinking fluids?"
    },
    {
      "turn_number": 43,
      "time": "2199-01-29 08:08:00",
      "speaker": "Doctor",
      "text": "Exactly. Stay hydrated, eat small meals, and take your medications as adjusted. Follow up with your liver clinic soon."
    },
    {
      "turn_number": 44,
      "time": "2199-01-29 08:10:00",
      "speaker": "Patient",
      "text": "Will I start hepatitis C treatment?"
    },
    {
      "turn_number": 45,
      "time": "2199-01-29 08:12:00",
      "speaker": "Doctor",
      "text": "Your liver team will decide, but now that your kidneys are better, it’s a real option. They’ll contact you."
    },
    {
      "turn_number": 46,
      "time": "2199-01-29 08:14:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I feel much better already."
    },
    {
      "turn_number": 47,
      "time": "2199-01-29 08:16:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’re glad to see you improving. Take care, and don’t hesitate to call if anything changes."
    },
    {
      "turn_number": 48,
      "time": "2199-01-29 08:18:00",
      "speaker": "Patient",
      "text": "I will. Thanks again for explaining everything."
    },
    {
      "turn_number": 49,
      "time": "2199-01-29 08:20:00",
      "speaker": "Doctor",
      "text": "Of course. The nurse will go over your discharge instructions and medications before you leave."
    },
    {
      "turn_number": 50,
      "time": "2199-01-29 08:22:00",
      "speaker": "Patient",
      "text": "Okay, I’ll make sure to read them carefully."
    }
  ],
  "summary": {
    "admission_start": "2199-01-26 17:53:00",
    "admission_end": "2199-01-29 15:46:00",
    "summary_paragraph": "A 72-year-old woman with a history of liver transplant for HCV cirrhosis, chronic kidney disease, diabetes, and essential tremor was admitted due to dehydration and acute kidney injury following two weeks of diarrhea and poor oral intake. She presented with elevated creatinine, hyperkalemia, and non-anion gap metabolic acidosis. IV fluids were administered, leading to improvement in renal function. Diarrhea resolved during admission, and stool studies were negative for common pathogens. Tacrolimus levels were initially elevated, prompting a dose reduction to 1 mg twice daily, with instructions to monitor levels post-discharge. CMV, viral, and parasitic studies were negative. She was discharged home in stable condition with plans to follow up on hepatitis C treatment eligibility given improved kidney function and to monitor tacrolimus levels closely.",
    "problems": [
      "Dehydration",
      "Acute kidney failure with lesion of tubular necrosis",
      "Diarrhea",
      "Chronic kidney disease, unspecified",
      "Complications of transplanted liver",
      "Acidosis",
      "Cirrhosis of liver without mention of alcohol",
      "Adult failure to thrive",
      "Anorexia",
      "Unspecified protein-calorie malnutrition",
      "Diabetes mellitus without mention of complication, type II or unspecified type, not stated as uncontrolled",
      "Chronic hepatitis C without mention of hepatic coma",
      "Depressive disorder, not elsewhere classified",
      "Essential and other specified forms of tremor",
      "Personal history of noncompliance with medical treatment, presenting hazards to health",
      "Loss of weight",
      "Esophageal reflux",
      "Personal history of peptic ulcer disease",
      "Acquired absence of organ, stomach",
      "Unspecified glaucoma",
      "Disorder of bone and cartilage, unspecified"
    ]
  }
}
